<template><div><el-alert v-if="criticalCount" :title="`${criticalCount} 个严重节点正在影响业务`" type="error" show-icon :closable="false"/><GTopology :nodes="nodes" :edges="edges" title="告警影响拓扑" @select="$emit('select',$event)"/></div></template>
<script setup lang="ts">import{computed}from'vue';import{GTopology}from'../GTopology';import type{TopologyNode,TopologyEdge}from'../GTopology/types';const p=defineProps<{nodes:TopologyNode[];edges:TopologyEdge[]}>();defineEmits<{(e:'select',id:string):void}>();const criticalCount=computed(()=>p.nodes.filter(n=>n.status==='danger').length);</script>
